import { AVATAR_IDS, type AvatarId } from '../../shared/profile';

export type Avatar = {
  id: AvatarId;
  label: string;
  kind: 'female' | 'male' | 'neutral';
  /** Bundled asset id from `require()`, which is what expo-image expects. */
  source: number;
};

/**
 * Bundled illustrated avatars — four women, one man, five abstract options for
 * people who would rather not use a face. Generated by scripts/generate-avatars.py;
 * ids must stay in sync with `AVATAR_IDS` in shared/profile.ts.
 */
export const AVATARS: Avatar[] = [
  { id: 'a1', label: 'Woman, long hair', kind: 'female', source: require('@/assets/images/avatars/a1.webp') },
  { id: 'a2', label: 'Woman, bun', kind: 'female', source: require('@/assets/images/avatars/a2.webp') },
  { id: 'a3', label: 'Woman, curly hair', kind: 'female', source: require('@/assets/images/avatars/a3.webp') },
  { id: 'a4', label: 'Woman, bob', kind: 'female', source: require('@/assets/images/avatars/a4.webp') },
  { id: 'a5', label: 'Man, short hair', kind: 'male', source: require('@/assets/images/avatars/a5.webp') },
  { id: 'a6', label: 'House', kind: 'neutral', source: require('@/assets/images/avatars/a6.webp') },
  { id: 'a7', label: 'Map pin', kind: 'neutral', source: require('@/assets/images/avatars/a7.webp') },
  { id: 'a8', label: 'Land and sun', kind: 'neutral', source: require('@/assets/images/avatars/a8.webp') },
  { id: 'a9', label: 'Rolling land', kind: 'neutral', source: require('@/assets/images/avatars/a9.webp') },
  { id: 'a10', label: 'Shapes', kind: 'neutral', source: require('@/assets/images/avatars/a10.webp') },
];

export const AVATAR_GROUPS: { title: string; kind: Avatar['kind']; ids: AvatarId[] }[] = [
  { title: 'Women', kind: 'female', ids: ['a1', 'a2', 'a3', 'a4'] },
  { title: 'Man', kind: 'male', ids: ['a5'] },
  { title: 'Other styles', kind: 'neutral', ids: ['a6', 'a7', 'a8', 'a9', 'a10'] },
];

const byId = new Map<string, Avatar>(AVATARS.map((avatar) => [avatar.id, avatar]));

/** Unknown or missing ids fall back to null so the UI can show initials. */
export function avatarSource(id: string | null | undefined): number | null {
  if (!id) return null;
  return byId.get(id)?.source ?? null;
}

export function avatarLabel(id: string | null | undefined): string {
  return (id && byId.get(id)?.label) || 'No avatar';
}

export { AVATAR_IDS };
